#ifndef ALGOL_TABLES_H
#define ALGOL_TABLES_H

#include <cstddef>
#include <span>
#include <stdexcept>

#include "stdarray.h"

//
// Tables of the original compiler, at their original addresses.
// Data in tables_data.cpp, generated by scripts/gen-tables.py; see doc/tables.md.
//
namespace tables {

struct Table {
    unsigned addr{};             // original address of the first word
    std::span<const Word> words; // contents

    unsigned end() const { return addr + words.size(); }

    // Word at an original address.
    Word at(unsigned address) const
    {
        if (address < addr || address >= end())
            throw std::out_of_range("table address out of range");
        return words[address - addr];
    }
};

struct InitWord {
    unsigned addr{};
    Word value{};
};

extern const InitWord workspace_init[];
extern const size_t workspace_init_size;

extern const Table symattr, warnings, chclass, syntext, errclass, p2msg, p2disp, p3class, p3mask,
    p3rewr, p3jump, p3regs, template_, p4disp, linetab, isotext, rtnames, summary;

} // namespace tables

#endif
